const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bob.obj");

const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};

const originalPts = normalizeVectors(vertices.map(vertex => vec(...vertex)));
let pts = originalPts.slice();

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const sigma = 0.05;
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
const k = Math.min(32, pts.length);
const {eigenvalues, eigenvectors} = laplacian.eigen({maxFirst: false, k});
const eigenArrays = eigenvectors.map(eigenvector => eigenvector.toArray());

const maxH = 10;
let h = 1;
let ite = 1;

const points = pts.map(point => point.toArray());
const pointPlot = IO.plotPointCloud(points, {color: [0.5, 0.5, 0.5]});
const rasterPlot = IO.raster(points, faces, {color: [0.5, 0.5, 0.5]});

const updatePlot = () => {
    const newPoints = pts.map(point => point.toArray());
    pointPlot.update(newPoints, {color: [0.5, 0.5, 0.5]});
    rasterPlot.update(newPoints, faces, {color: [0.5, 0.5, 0.5]});
    pointPlot.render();
    rasterPlot.render();
};

const takeFlowStep = () => {
    const dim = pts[0].components.length;

    // 1. Spectral smoothing step (exp(-L_0 h) x exact on the first k eigenmodes)
    const flowedCoordinates = Array(dim).fill(0).map((_, d) => {
        const x = pts.map(point => point.components[d]);
        const flowed = x.slice();
        for (let m = 0; m < k; m++) {
            const u = eigenArrays[m];
            let coefficient = 0;
            for (let p = 0; p < x.length; p++) coefficient += u[p] * x[p];
            const gain = Math.exp(-eigenvalues[m] * h) * coefficient;
            for (let p = 0; p < x.length; p++) flowed[p] += gain * u[p];
        }
        return vec(...flowed);
    });

    const flowedPts = pts.map((_, i) => vec(...flowedCoordinates.map(coordinate => coordinate.components[i])));

    // 2. Center to origin
    const mean = flowedPts.reduce((sum, point) => sum.add(point), vec.zero(dim)).scale(1 / flowedPts.length);
    pts = flowedPts.map(point => point.sub(mean));
};

const runIntegration = () => {
    for (let i = 0; i < ite; i++) {
        takeFlowStep();
    }
    updatePlot();
};

const resetSimulation = () => {
    pts = originalPts.slice();
    updatePlot();
};

resetSimulation();

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => rasterPlot},
    ]},
    {type: "group", value: () => [
        {type: "button", value: () => ({title: "Reset", onClick: resetSimulation})},
        {type: "button", value: () => ({title: "Integrate", onClick: runIntegration})},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: maxH,
        step: maxH / 100,
        value: h,
        title: "Time step h:",
        onChange: value => { h = value; },
    })},
    {type: "slider", value: () => ({
        min: 1,
        max: 100,
        step: 1,
        value: ite,
        title: "Iterations (ite):",
        onChange: value => { ite = Math.round(value); },
    })},
);
ui;
